    Bug 2019325 - Close new calendar read dialog when switching tabs. r=arschmitz

    Differential Revision: https://phabricator.services.mozilla.com/D284872

diff --git a/calendar/base/content/calendar-modes.js b/calendar/base/content/calendar-modes.js
index 5400e426943..7e900efc639 100644
--- a/calendar/base/content/calendar-modes.js
+++ b/calendar/base/content/calendar-modes.js
@@ -46,6 +46,10 @@ function changeMode(mode = "mail") {
     elem.setAttribute("current", gCurrentMode);
   });

+  // The new calendar dialog should be hidden when switching mode, since it will
+  // otherwise overlay whatever tab we switch to.
+  document.getElementById("calendarDialog")?.close();
+
   TodayPane.onModeModified();
 }

diff --git a/mail/components/calendar/test/browser/browser_calendarDialogIntegration.js b/mail/components/calendar/test/browser/browser_calendarDialogIntegration.js
index 2eac1916f09..f38b1d6abb2 100644
--- a/mail/components/calendar/test/browser/browser_calendarDialogIntegration.js
+++ b/mail/components/calendar/test/browser/browser_calendarDialogIntegration.js
@@ -24,6 +24,7 @@ add_setup(() => {

   registerCleanupFunction(() => {
     CalendarTestUtils.removeCalendar(calendar);
+    tabmail.closeOtherTabs(0);
   });
 });

@@ -210,3 +211,32 @@ add_task(async function test_resizeWindow() {

   style.remove();
 });
+
+add_task(async function test_closeDialogOnTabSwitch() {
+  await createEvent({ calendar });
+  const eventBox = await openAndShowEvent();
+
+  const dialog = document.querySelector(`[is="calendar-dialog"]`);
+
+  Assert.ok(dialog.open, "Dialog should be open");
+
+  const dialogClose = BrowserTestUtils.waitForEvent(dialog, "close");
+  tabmail.switchToTab(0);
+  await dialogClose;
+
+  Assert.ok(!dialog.open, "Dialog should report it is closed");
+  Assert.ok(BrowserTestUtils.isHidden(dialog), "Dialog should not be visible");
+
+  await CalendarTestUtils.openCalendarTab(window);
+
+  Assert.ok(
+    !dialog.open,
+    "Dialog should stay closed after switching back to calendar tab"
+  );
+  Assert.ok(
+    BrowserTestUtils.isHidden(dialog),
+    "Dialog should still not be visible"
+  );
+
+  await calendar.deleteItem(eventBox.occurrence);
+});
